    if(argc < 2) return 1;
    FILE* f = fopen(argv[1], "rb");
    if(!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t* buf = malloc(n ? n : 1);
    size_t r = fread(buf, 1, n, f);
    fclose(f);
    int ret = LLVMFuzzerTestOneInput(buf, r);
    free(buf);
    return ret;
}
