int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

static uint32_t rng_state = 0x12345678;
static uint32_t xrand(void) {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

static const uint8_t interesting[] = {
    '(', ')', '[', ']', '"', '\'', '\\', '\n', '\r', '\t', ' ', '!',
    '<', '>', ':', ';', 0, 0xff, 0x80, 0x7f, 'a', 'A', '9', '.', '*', '_'
};

static uint8_t seed_text[65536];
static size_t seed_len = 0;

int main(int argc, char** argv) {
    if(argc < 2) { fprintf(stderr, "usage: %s <seedfile> [iters]\n", argv[0]); return 2; }
    FILE* f = fopen(argv[1], "rb");
    if(!f) { perror("fopen"); return 2; }
    seed_len = fread(seed_text, 1, sizeof(seed_text), f);
    fclose(f);

    long iters = (argc > 2) ? atol(argv[2]) : 100000;

    for(long it = 0; it < iters; it++) {
        /* Build input: 8 bytes flags + mutated text */
        uint8_t buf[65536];
        size_t n = 8;
        uint32_t flags = 0;
        /* occasionally set some flags */
        if((xrand() % 3) == 0) {
            static const uint32_t known_flags[] = {
                0,
                1u<<0, 1u<<1, 1u<<2, 1u<<3, 1u<<4, 1u<<5, 1u<<6, 1u<<7, 1u<<8,
                (1u<<0)|(1u<<1), (1u<<2)|(1u<<4), 0xFFFFFFFFu
            };
            flags = known_flags[xrand() % (sizeof(known_flags)/sizeof(known_flags[0]))];
        }
        memcpy(buf, &flags, 4);
        uint32_t rflags = xrand();
        memcpy(buf+4, &rflags, 4);

        /* copy seed with mutations */
        size_t len = seed_len;
        if(len > 60000) len = 60000;
        memcpy(buf+n, seed_text, len);
        size_t text_len = len;

        /* random number of mutation operations */
        int nmut = 1 + (xrand() % 12);
        for(int m = 0; m < nmut; m++) {
            size_t pos = xrand() % (text_len + 1);
            switch(xrand() % 6) {
                case 0: /* insert */
                    if(text_len < 60000) {
                        memmove(buf+8+pos+1, buf+8+pos, text_len - pos);
                        buf[8+pos] = interesting[xrand() % sizeof(interesting)];
                        text_len++;
                    }
                    break;
                case 1: /* delete */
                    if(text_len > 0) {
                        pos = xrand() % text_len;
                        memmove(buf+8+pos, buf+8+pos+1, text_len - pos - 1);
                        text_len--;
                    }
                    break;
                case 2: /* flip byte */
                    if(text_len > 0) {
                        pos = xrand() % text_len;
                        buf[8+pos] ^= (uint8_t)(1u << (xrand() % 8));
                    }
                    break;
                case 3: /* set interesting */
                    if(text_len > 0) {
                        pos = xrand() % text_len;
                        buf[8+pos] = interesting[xrand() % sizeof(interesting)];
                    }
                    break;
                case 4: /* overwrite with a chunk of interesting bytes */
                    if(text_len < 60000) {
                        size_t chunk = 1 + xrand() % 8;
                        if(pos + chunk > 60000) chunk = 60000 - pos;
                        for(size_t i = 0; i < chunk; i++)
                            buf[8+pos+i] = interesting[xrand() % sizeof(interesting)];
                    }
                    break;
                case 5: /* duplicate a chunk */
                    if(text_len < 60000 && text_len > 4) {
                        size_t chunk = 1 + xrand() % 16;
                        size_t src = xrand() % (text_len - chunk);
                        if(pos + chunk <= 60000) {
                            memmove(buf+8+pos+chunk, buf+8+pos, text_len - pos);
                            memcpy(buf+8+pos, buf+8+src, chunk);
                            text_len += chunk;
                        }
                    }
                    break;
            }
        }
        size_t total = 8 + text_len;

        pid_t pid = fork();
        if(pid == 0) {
            /* child: run the target, redirect stderr to /dev/null */
            int devnull = open("/dev/null", O_WRONLY);
            dup2(devnull, 2);
            close(devnull);
            _exit(LLVMFuzzerTestOneInput(buf, total));
        }
        int status;
        waitpid(pid, &status, 0);
        if(WIFSIGNALED(status) || (WIFEXITED(status) && WEXITSTATUS(status) != 0)) {
            /* crash or abnormal exit: save the input */
            char fname[64];
            snprintf(fname, sizeof(fname), "/gt/_work/crash_%06ld.bin", it);
            FILE* out = fopen(fname, "wb");
            if(out) { fwrite(buf, 1, total, out); fclose(out); }
            fprintf(stderr, "CRASH at iter %ld status=0x%x saved=%s\n", it, status, fname);
            return 0;
        }
        if((it % 5000) == 0)
            fprintf(stderr, "iter %ld\n", it);
    }
    fprintf(stderr, "no crash in %ld iters\n", iters);
    return 0;
}
