#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/wait.h>
#include <sys/types.h>

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

static uint32_t rng_state = 0x9e3779b9;
static uint32_t xrand(void) {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

static const uint8_t interesting[] = {
    '(', ')', '[', ']', '"', '\'', '\\', '\n', '\r', '\t', ' ', '!',
    '<', '>', ':', ';', 0, 0xff, 0x80, 0x7f, 'a', 'A', '9', '.', '*', '_', '-'
};

static uint8_t seed_text[65536];
static size_t seed_len = 0;

/* returns 1 if child log contains the sink event with off past ctx size */
static int check_log(void) {
    char buf[4096];
    int fd = open("/gt/_work/child_log.txt", O_RDONLY);
    if(fd < 0) return 0;
    int n = read(fd, buf, sizeof(buf)-1);
    close(fd);
    if(n <= 0) return 0;
    buf[n] = 0;
    return (strstr(buf, "link_title_sink") != NULL) && (strstr(buf, "off_past_ctx_size=1") != NULL);
}

int main(int argc, char** argv) {
    if(argc < 2) { fprintf(stderr, "usage: %s <seedfile> [iters]\n", argv[0]); return 2; }
    FILE* f = fopen(argv[1], "rb");
    if(!f) { perror("fopen"); return 2; }
    seed_len = fread(seed_text, 1, sizeof(seed_text), f);
    fclose(f);

    long iters = (argc > 2) ? atol(argv[2]) : 200000;

    for(long it = 0; it < iters; it++) {
        uint8_t buf[65536];
        /* flags: force ADMONITIONS often; sometimes add others */
        uint32_t flags = 0x80000; /* MD_FLAG_ADMONITIONS */
        if((xrand() % 2) == 0)
            flags |= (xrand() % 0x1000);
        memcpy(buf, &flags, 4);
        uint32_t rflags = xrand();
        memcpy(buf+4, &rflags, 4);

        size_t len = seed_len;
        if(len > 60000) len = 60000;
        memcpy(buf+8, seed_text, len);
        size_t text_len = len;

        int nmut = 1 + (xrand() % 14);
        for(int m = 0; m < nmut; m++) {
            size_t pos = xrand() % (text_len + 1);
            switch(xrand() % 6) {
                case 0:
                    if(text_len < 60000) {
                        memmove(buf+8+pos+1, buf+8+pos, text_len - pos);
                        buf[8+pos] = interesting[xrand() % sizeof(interesting)];
                        text_len++;
                    }
                    break;
                case 1:
                    if(text_len > 0) {
                        pos = xrand() % text_len;
                        memmove(buf+8+pos, buf+8+pos+1, text_len - pos - 1);
                        text_len--;
                    }
                    break;
                case 2:
                    if(text_len > 0) {
                        pos = xrand() % text_len;
                        buf[8+pos] ^= (uint8_t)(1u << (xrand() % 8));
                    }
                    break;
                case 3:
                    if(text_len > 0) {
                        pos = xrand() % text_len;
                        buf[8+pos] = interesting[xrand() % sizeof(interesting)];
                    }
                    break;
                case 4:
                    if(text_len < 60000) {
                        size_t chunk = 1 + xrand() % 8;
                        if(pos + chunk > 60000) chunk = 60000 - pos;
                        for(size_t i = 0; i < chunk; i++)
                            buf[8+pos+i] = interesting[xrand() % sizeof(interesting)];
                    }
                    break;
                case 5:
                    if(text_len < 60000 && text_len > 4) {
                        size_t chunk = 1 + xrand() % 16;
                        size_t src = xrand() % (text_len - chunk);
                        if(pos + chunk <= 60000 && src + chunk <= text_len) {
                            static uint8_t tmp[64];
                            memcpy(tmp, buf+8+src, chunk);
                            memmove(buf+8+pos+chunk, buf+8+pos, text_len - pos);
                            memcpy(buf+8+pos, tmp, chunk);
                            text_len += chunk;
                        }
                    }
                    break;
            }
        }
        size_t total = 8 + text_len;

        pid_t pid = fork();
        if(pid == 0) {
            int logfd = open("/gt/_work/child_log.txt", O_WRONLY|O_CREAT|O_TRUNC, 0644);
            dup2(logfd, 2);
            close(logfd);
            _exit(LLVMFuzzerTestOneInput(buf, total));
        }
        int status;
        waitpid(pid, &status, 0);
        int crashed = WIFSIGNALED(status) || (WIFEXITED(status) && WEXITSTATUS(status) != 0);
        int sink = check_log();
        if(crashed || sink) {
            char fname[64];
            snprintf(fname, sizeof(fname), "/gt/_work/found_%06ld.bin", it);
            FILE* out = fopen(fname, "wb");
            if(out) { fwrite(buf, 1, total, out); fclose(out); }
            fprintf(stderr, "FOUND at iter %ld status=0x%x sink=%d saved=%s\n", it, status, sink, fname);
            return 0;
        }
        if((it % 10000) == 0)
            fprintf(stderr, "iter %ld\n", it);
    }
    fprintf(stderr, "no hit in %ld iters\n", iters);
    return 0;
}
